text:
{
  "requirements": [
    {
      "id": "r1",
      "label": "Vendor Questions Worksheet Completion",
      "rfpQuote": "Provide a detailed response to each question.",
      "section": "§0"
    },
    {
      "id": "r2",
      "label": "Sole Contact Information",
      "rfpQuote": "Bidder’s sole contact person during the Solicitation process. Include name, title, address, email, and phone number.",
      "section": "§0"
    },
    {
      "id": "r3",
      "label": "Authorized Signer Details",
      "rfpQuote": "Person authorized to receive and sign a resulting contract. Include name, title, address, email, phone number and vendor customer code",
      "section": "§0"
    },
    {
      "id": "r4",
      "label": "Company Background Information",
      "rfpQuote": "Legal business name and address. Include business entity designation, e.g., sole proprietor, Inc., LLC, or LLP.",
      "section": "§0"
    },
    {
      "id": "r5",
      "label": "Organizational Structure Changes",
      "rfpQuote": "Has there been a recent change in organizational structure (e.g., management team) or control",
      "section": "§0"
    },
    {
      "id": "r6",
      "label": "Debarment and Litigation Disclosures",
      "rfpQuote": "Has bidder ever been debarred, suspended, or disqualified from bidding or contracting with any entity",
      "section": "§1"
    },
    {
      "id": "r7",
      "label": "Gross Annual Sales and Scale-Up Plan",
      "rfpQuote": "State your gross annual sales for each of the last 5 years.",
      "section": "§1"
    },
    {
      "id": "r8",
      "label": "Contract Work Physical Address",
      "rfpQuote": "State the physical address of the place of business that would have primary responsibility for this account",
      "section": "§2"
    },
    {
      "id": "r9",
      "label": "Disabled Veteran Qualifications",
      "rfpQuote": "To demonstrate qualification as a qualified disabled veteran, you must provide:",
      "section": "§3"
    },
    {
      "id": "r10",
      "label": "Prior Relevant Experience",
      "rfpQuote": "Describe at least [3]relevant experiences from the last[5]years supporting your ability to successfully manage a contract",
      "section": "§4"
    },
    {
      "id": "r11",
      "label": "Standard Contract Terms Agreement",
      "rfpQuote": "Bidder must affirm agreement with the attached Contract Terms.",
      "section": "§11"
    },
    {
      "id": "r12",
      "label": "Schedule C Insurance Agreement",
      "rfpQuote": "Bidder must affirm agreement with the attached Schedule C (Insurance Requirements).",
      "section": "§12"
    },
    {
      "id": "r13",
      "label": "Michigan Economic Impact Disclosures",
      "rfpQuote": "Number of employees currently employed at locations within the State of Michigan.",
      "section": "§12"
    },
    {
      "id": "r14",
      "label": "Compliance Disclosures",
      "rfpQuote": "Bidder must disclose any violations of state or federal labor, antidiscrimination and employment laws",
      "section": "§12"
    },
    {
      "id": "r15",
      "label": "EEO-1 Demographic Reporting",
      "rfpQuote": "Bidder shall provide a copy of their current EEO-1 demographic report",
      "section": "§12"
    },
    {
      "id": "r16",
      "label": "Business Specifications Worksheet Response",
      "rfpQuote": "Bidder must respond to each requirement or question marked “BIDDER RESPONSE” below",
      "section": "§13"
    },
    {
      "id": "r17",
      "label": "Salesforce Support Hours Delivery",
      "rfpQuote": "Vendor will provide up to 600 hours of Salesforce maintenance and Support Services each year",
      "section": "§3"
    },
    {
      "id": "r18",
      "label": "Hosting Application Disclosure",
      "rfpQuote": "Bidder must disclose if it is proposing a Contractor Hosted or State Hosted application.",
      "section": "§4"
    },
    {
      "id": "r19",
      "label": "Digital Accessibility Compliance",
      "rfpQuote": "All websites, applications, software, and associated content and documentation provided by the Contractor as part of the Solution must comply with the Digital Accessibility Standards.",
      "section": "§5"
    },
    {
      "id": "r20",
      "label": "Identity Federation Integration",
      "rfpQuote": "The Contractor must implement identity federation with the State’s MiLogin IT Identity and Access Management (IAM) environment",
      "section": "§7"
    },
    {
      "id": "r21",
      "label": "Data Retention and Retrieval Description",
      "rfpQuote": "Bidder must review and explain how the data retention, disposal, and retrieval requirements will be met",
      "section": "§8"
    },
    {
      "id": "r22",
      "label": "Browser Compatibility Support",
      "rfpQuote": "Contractor must ensure applications and websites display and function accurately in, at minimum, the two most recent major versions",
      "section": "§9"
    },
    {
      "id": "r23",
      "label": "Application Look and Feel Compliance",
      "rfpQuote": "All software items provided by the Contractor must adhere to the State of Michigan Application/Site standards",
      "section": "§10.1"
    },
    {
      "id": "r24",
      "label": "MiLogin and Salesforce Integration",
      "rfpQuote": "Contractor must integrate their solution to the following technologies: 1 - MiLogin 2 - Salesforce",
      "section": "§11"
    },
    {
      "id": "r25",
      "label": "Training Plan and Services",
      "rfpQuote": "The Contractor must provide administration and end-user training for implementation, go-live support, and operational handoff.",
      "section": "§14"
    },
    {
      "id": "r26",
      "label": "Transition-In and Transition-Out Plan",
      "rfpQuote": "Bidder must provide a detailed transition-in and transition-out plan in Schedule G – Transition In and Out Plan",
      "section": "§15"
    },
    {
      "id": "r27",
      "label": "Solution and User Documentation",
      "rfpQuote": "Contractor must provide all user manuals, operating manuals, technical manuals and any other instructions, specifications, documents or materials",
      "section": "§16"
    },
    {
      "id": "r28",
      "label": "Contractor Key Personnel Roles",
      "rfpQuote": "Contractor resource who is responsible to serve as the primary contact with regard to services",
      "section": "§19"
    },
    {
      "id": "r29",
      "label": "ICHAT and Drug Screening Certifications",
      "rfpQuote": "Contractor must present certifications evidencing satisfactory ICHAT and drug test results for all staff identified for assignment",
      "section": "§20"
    },
    {
      "id": "r30",
      "label": "Meetings Facilitation",
      "rfpQuote": "the Contractor Project Manager must facilitate a project kick off meeting with the support from the State’s Project Manager",
      "section": "§22"
    },
    {
      "id": "r31",
      "label": "Weekly Project Monitoring Reporting",
      "rfpQuote": "the Contractor Project Manager will monitor project implementation progress and report on a weekly basis to the State’s Project Manager",
      "section": "§23"
    },
    {
      "id": "r32",
      "label": "Clarity PPM Timesheet Entry",
      "rfpQuote": "All Contractors must submit and enter weekly timesheets into the State of Michigan’s Project Portfolio Management tool, Clarity PPM",
      "section": "§23"
    },
    {
      "id": "r33",
      "label": "SUITE Methodology Implementation",
      "rfpQuote": "the Contractor is required to utilize the applicable State Unified Information Technology Environment (SUITE) methodologies",
      "section": "§24.1"
    },
    {
      "id": "r34",
      "label": "Salesforce Release Readiness Execution",
      "rfpQuote": "Contractor performs detailed Salesforce Release Readiness prior to the scheduled release.",
      "section": "§27"
    },
    {
      "id": "r35",
      "label": "Bug and Defect Resolution",
      "rfpQuote": "Contractor develops, tests, and delivers for implementation the identified solution of any identified bugs/defects.",
      "section": "§29"
    },
    {
      "id": "r36",
      "label": "Azure DevOps ALM Usage",
      "rfpQuote": "Use Azure ADO for Application lifecycle management to track backlogs, defects, test cases, releases etc",
      "section": "§32"
    },
    {
      "id": "r37",
      "label": "Baseline Source and Version Control",
      "rfpQuote": "create baseline source code and implement version control for any config/code changes going forward.",
      "section": "§34"
    },
    {
      "id": "r38",
      "label": "Platform Release Test Cases",
      "rfpQuote": "Build test cases for SF Platform Releases regression testing",
      "section": "§36"
    },
    {
      "id": "r39",
      "label": "CI/CD Pipeline Setup",
      "rfpQuote": "Contractor must set up CI/CD pipelines to SIT, UAT and Prod environments to deploy Metadata changes",
      "section": "§38"
    },
    {
      "id": "r40",
      "label": "Manual Deployment Move Docs",
      "rfpQuote": "Contractor will attach move docs that will contain step by step instructions for manually deploying non-metadata changes",
      "section": "§39"
    },
    {
      "id": "r41",
      "label": "RFC Release Coordination",
      "rfpQuote": "Contractor must coordinate with MPSC/DTMB on a regular cadence to plan future releases and complete theRequestforChange (RFC)",
      "section": "§40"
    },
    {
      "id": "r42",
      "label": "Security Vulnerability Remediation",
      "rfpQuote": "Contractor is responsible to address any security vulnerabilities from the DAST, SAST and SCA scans for yearly ATO",
      "section": "§42"
    },
    {
      "id": "r43",
      "label": "Disaster Recovery Testing Coordination",
      "rfpQuote": "Contractor is responsible to coordinate with MPSC for the Disaster Recovery table-top testing.",
      "section": "§43"
    },
    {
      "id": "r44",
      "label": "Backup and Recovery Implementation",
      "rfpQuote": "Contractor must implement “own” backup or another backup and recovery process for all the MPSC orgs",
      "section": "§43"
    }
  ],
  "constraints": [
    {
      "id": "c1",
      "kind": "OTHER",
      "label": "Annual Support Hours Cap",
      "rfpQuote": "No work in excess of the number of hours stated in this agreement will be performed without an executed change order.",
      "section": "§3"
    },
    {
      "id": "c2",
      "kind": "SCOPE",
      "label": "Support Hours Allocation",
      "rfpQuote": "These 600 hours will be divided equally to support the CAD/Telecom (200 hours), E-Dockets (200 hours) and Pipeline Safety (200 hours)",
      "section": "§3"
    },
    {
      "id": "c3",
      "kind": "DEADLINE",
      "label": "Contract Agreement Term",
      "rfpQuote": "Term of the Agreement: 5 base years with 5 - 1 year options",
      "section": "§3"
    },
    {
      "id": "c4",
      "kind": "OTHER",
      "label": "Data Destruction Restriction",
      "rfpQuote": "Contractor will not dispose of, delete, or destroy State Data without the prior written approval of the State.",
      "section": "§8"
    },
    {
      "id": "c5",
      "kind": "BUDGET",
      "label": "Standard IT Environment Cost",
      "rfpQuote": "Contractor must support the current and future State standard environment at no additional cost to the State.",
      "section": "§9"
    },
    {
      "id": "c6",
      "kind": "LEGAL",
      "label": "Geographic System Access Restriction",
      "rfpQuote": "Contractor will not access State environments or State Systems from locations outside the United States",
      "section": "§10.1"
    },
    {
      "id": "c7",
      "kind": "LEGAL",
      "label": "Offshore Resources Prohibition",
      "rfpQuote": "Use of Offshore Resources is prohibited per the Schedule E – Data Security Requirements.",
      "section": "§20.1"
    },
    {
      "id": "c8",
      "kind": "OTHER",
      "label": "Contractor Staffing Replacement Approval",
      "rfpQuote": "Contractor must seek approval from the State prior to removing or replacing any Contractor Personnel with access to State Data.",
      "section": "§20.1"
    },
    {
      "id": "c9",
      "kind": "BUDGET",
      "label": "Contractor Personnel Equipment Costs",
      "rfpQuote": "Contractor will pay for all equipment needed Contractor Personnel to meet requirements.",
      "section": "§20.1"
    },
    {
      "id": "c10",
      "kind": "BUDGET",
      "label": "Mandatory Meeting Attendance Cost",
      "rfpQuote": "The Contractor must attend the following meetings, at a location and time as identified by the State, at no additional cost",
      "section": "§22"
    },
    {
      "id": "c11",
      "kind": "SCOPE",
      "label": "Business Specifications Modification Restriction",
      "rfpQuote": "Contractor must not alter the document.",
      "section": "§26"
    },
    {
      "id": "c12",
      "kind": "OTHER",
      "label": "Specification Response Word Limit",
      "rfpQuote": "Description must be no more than 250 words for each business Specification.",
      "section": "§27"
    }
  ],
  "suggestedWeights": [
    {
      "criterionId": "problem_understanding",
      "weight": 1.2,
      "reason": "Demonstrating understanding of the three distinct Salesforce Orgs (CAD/Telecom, E-Dockets, Pipeline Safety) and integration with MiLogin is crucial."
    },
    {
      "criterionId": "scope_clarity",
      "weight": 1.5,
      "reason": "The client tightly scopes work to 600 hours annually across specific environments and mandates responding to all business specifications."
    },
    {
      "criterionId": "pricing_clarity",
      "weight": 1.0,
      "reason": "Standard hourly support and change notice processes are outlined without complex bespoke pricing models described in this section."
    },
    {
      "criterionId": "timeline_clarity",
      "weight": 1.1,
      "reason": "Adherence to release cycles, scheduled meetings, and a defined 5-year base term requires clear operational schedules."
    },
    {
      "criterionId": "tone_persuasiveness",
      "weight": 0.8,
      "reason": "The procurement document heavily emphasizes strict procedural and compliance responses over marketing language."
    },
    {
      "criterionId": "risk_transparency",
      "weight": 1.4,
      "reason": "Business specification entries explicitly mandate identifying risks related to configurations, customizations, and hour allocations."
    },
    {
      "criterionId": "completeness",
      "weight": 1.5,
      "reason": "The State requires comprehensive disclosures across the Vendor Worksheet, standard terms affirmation, and each row of the Business Specifications."
    }
  ]
}
